        2: { totalCodewords: 44, ecBlocks: [{ ecLevel: 'L', ecCodewords: 10, blockCount: 1 }, { ecLevel: 'M', ecCodewords: 16, blockCount: 1 }, { ecLevel: 'Q', ecCodewords: 22, blockCount: 1 }, { ecLevel: 'H', ecCodewords: 28, blockCount: 1 }] },
        // ... (additional versions would be defined here)
        40: { totalCodewords: 370, ecBlocks: [{ ecLevel: 'L', ecCodewords: 30, blockCount: 2 }, { ecLevel: 'M', ecCodewords: 60, blockCount: 2 }, { ecLevel: 'Q', ecCodewords: 90, blockCount: 2 }, { ecLevel: 'H', ecCodewords: 120, blockCount: 2 }] }
